import java.util.*;

class Solution {
    public int countMisplaced(int[] heights) {
        int[] cnt = new int[101];
        for (int h : heights) cnt[h]++;
        int bad = 0, k = 0;
        // Rebuild the sorted line height by height and compare on the fly
        for (int v = 1; v <= 100; v++) {
            for (int c = 0; c < cnt[v]; c++) {
                if (heights[k] != v) bad++;
                k++;
            }
        }
        return bad;
    }
}

